export function benchmarkWidgetLabel(product: { name: string; price: number; rating: number }): string {
  if (product.rating >= 4.5) {
    return `Best Seller: ${product.name} - $${product.price.toFixed(2)}`;
  } else if (product.rating >= 3.5) {
    return `Popular: ${product.name} - $${product.price.toFixed(2)}`;\n  } else {
    return `New Arrival: ${product.name} - $${product.price.toFixed(2)}`;
  }
}
